return $input.all().map((item, index) => {
  const source = $('Kildeliste').all()[index].json;
  const title = String(item.json.title ?? '').replace(/\s+/g, ' ').trim();
  let text = String(item.json.text ?? '').replace(/\s+/g, ' ').trim();
  if (!title || !text || !source.id) throw new Error('Kilden mangler titel, tekst eller id.');
  const pos = text.toLocaleLowerCase('da-DK').indexOf(title.toLocaleLowerCase('da-DK'));
  if (pos >= 0) text = text.slice(pos);
  let embassy_address = null;
  if (source.id === 'es-ambassade-kontakt') {
    const match = text.match(/Calle Serrano\s+26,?\s*7\.?\s*28001\s+Madrid/i);
    if (!match) throw new Error('Ambassadeadressen kunne ikke udtrækkes. Kontrollér kildesidens format.');
    embassy_address = match[0];
  }
  return {json: {...source, ...item.json, source_id: source.id, source_url: source.url,
    title, text, character_count: text.length, embassy_address,
    embassy_id: embassy_address ? 'dk-madrid' : null,
    embassy_name: embassy_address ? 'Danmarks ambassade i Spanien' : null,
    embassy_city: embassy_address ? 'Madrid' : null}, pairedItem: {item: index}};
});

const output = [];
const chunkSize = 800;
const overlap = 150;

for (const [inputIndex, item] of $input.all().entries()) {
  const { text, ...metadata } = item.json;
  const content = String(text ?? '').trim();

  if (!content || !metadata.source_id) {
    throw new Error('Tekst eller source_id mangler.');
  }

  const outputStart = output.length;
  let start = 0;
  let chunkIndex = 0;

  while (start < content.length) {
    let end = Math.min(start + chunkSize, content.length);

    // Undgå så vidt muligt at klippe midt i et ord.
    if (end < content.length) {
      const lastSpace = content.lastIndexOf(' ', end);
      if (lastSpace > start + overlap) {
        end = lastSpace;
      }
    }

    const chunkText = content.slice(start, end).trim();

    output.push({
      json: {
        ...metadata,
        chunk_id: `${metadata.source_id}-${chunkIndex}`,
        chunk_index: chunkIndex,
        chunk_text: chunkText,
        chunk_character_count: chunkText.length
      },
      pairedItem: { item: inputIndex }
    });

    if (end === content.length) break;

    start = end - overlap;

    // Start næste chunk ved begyndelsen af et ord.
    while (start > 0 && content[start - 1] !== ' ') {
      start--;
    }

    chunkIndex++;
  }
  for (const chunk of output.slice(outputStart)) chunk.json.chunk_count = chunkIndex + 1;
}

return output;

// Find det tekststykke, som dette Ollama-svar tilhører.
const chunk = $('Opdel tekst i chunks').item.json;
const embedding = $json.embeddings?.[0];

if (
  !Array.isArray(embedding) ||
  embedding.length === 0 ||
  !embedding.every(value => Number.isFinite(value))
) {
  throw new Error('Ollama returnerede ikke en gyldig embedding.');
}

return {
  json: {
    ...chunk,
    embedding,
    embedding_model: $json.model,
    embedding_dimensions: embedding.length
  }
};

