  },
  {
    id: "es-ambassade-kontakt",
    title: "Kontakt til Danmarks ambassade i Spanien",
    url: "https://um.dk/spanien/om-os/kontakt-og-ekspedionstid/",
    country: "Spanien",
    country_id: "ES",
    topic: "repraesentation",
    publisher: "Udenrigsministeriet"
  },
  {
    id: "es-rejsevejledning",
    title: "Rejsevejledning for Spanien",
    url: "https://um.dk/rejse-og-ophold/rejse-til-udlandet/rejsevejledninger/spanien",
    country: "Spanien",
    country_id: "ES",
