  }
];

const retrievedAt = new Date().toISOString();

return sources.map(source => ({
  json: {
    ...source,
    retrieved_at: retrievedAt
  }
}));

const rows = $input.all();
for (const item of rows) {
  if (item.json.errors?.length) throw new Error(JSON.stringify(item.json.errors));
  if (!item.json.data?.values?.length) throw new Error('Neo4j returnerede ingen gemte chunks.');
}
return [{json:{imported_chunks:rows.length,status:'success'}}];
